// Groovy's wardrobe items, drawn in code (round 5 item 3, round 3E item 7):
// the shapes of docs/design/wardrobe-v2/Wardrobe.dc.html and Seasonal.dc.html
// (art/wardrobe.ts, art/seasonal.ts, generated by scripts/gen-art.py), in the
// boards' coordinates mapped onto his body (art/draw.ts), plus the Diamond
// crown, his six-month reward, drawn in the same style.
//
// Coordinates are BotEngine's body space: origin at the body centre, y down,
// R = W × 0.3, rx = 1.14 R, ry = 0.88 R. Items sit on named anchors taken from
// his live pillow outline (headAnchors, round 3H item 1; placed the way
// Coucou's items sit on its head, none of its art):
// - face items are mapped onto his real eyes (BotEngine.eyeCentres), so the
//   board's lenses land on them at any angle and narrow as the eyes do; the
//   arms of glasses run back to the sides of his head, behind him;
// - hats sit on the rim, an ellipse on his head whose ends lie on his outline
//   and whose height follows his nod; the far half of the rim is behind him;
// - neck items sit on the collar, the same kind of ellipse near his base,
//   its back half behind him;
// - the pool ring goes round his middle and only slides.
// Nothing is clipped to the body, so nothing is cut off at the edge. Hats
// drop on, glasses slide down into place and neck items pop in.

import { Ease } from "../core/anim";
import { drawShapes, type Art, type Shape } from "./art/draw";
import { SEASONAL_ART } from "./art/seasonal";
import { WARDROBE_ART } from "./art/wardrobe";
import { SLOT_OF } from "./appearance";
import type { Accessory, Outfit } from "./wardrobe";
import { PILLOW_BOW, halfWidthAt, pillowXY } from "./pillow";

type Ctx = CanvasRenderingContext2D;

/** Head geometry + the spring lag of the soft parts (−1…1, in head units). */
export interface Head {
  R: number;
  rx: number;
  ry: number;
  yaw: number;
  pitch: number;
  physDx: number;
  physDy: number;
  /** Pendulum angle of dangling parts (the engine's spring), 0 at rest. */
  swing?: number;
  /** His eyes in body space, left then right (the engine's); face items sit on them. */
  eyes?: [[number, number], [number, number]];
}

export function makeHead(R: number, yaw = 0, pitch = 0, physDx = 0, physDy = 0): Head {
  return { R, rx: R * 1.14, ry: R * 0.88, yaw, pitch, physDx, physDy };
}

/** An ellipse on his body: centre, half width (on his outline), half height. */
export interface Ring { cx: number; cy: number; a: number; b: number }

/** Named anchors taken from his live pillow outline (round 3H item 1), body space. */
export interface Anchors {
  /** The top of his head (the pillow's dipped crown). */
  crown: [number, number];
  /** Where a hat's rim meets his head; its ends lie on his outline. */
  rim: Ring;
  rimLeft: [number, number];
  rimRight: [number, number];
  rimTop: [number, number];
  eyeL: [number, number];
  eyeR: [number, number];
  eyeLine: number;
  /** Where a neck item goes round him, near the base; its ends lie on his outline. */
  collar: Ring;
  neck: [number, number];
  /** The bottom of his body. */
  base: number;
}

/** His outline's exponent (skins.ts SHAPE); the minis never wear items. */
const BODY_EXP = 3.0;
/** The rim's and the collar's height on him, as a fraction of ry. */
/** Where a hat's rim sits on his head (round 3M item 2: down on the crown, not on top of it). */
export const RIM_V = -0.5;
/** Where the boards' hats have their rim: the art's seat line. */
const ART_RIM_V = -0.72;
export const COLLAR_V = 0.8;

/**
 * Round 3M item 1, his head as a fake 3D body, drawn in 2D: an ellipsoid whose
 * rings follow his real outline (half width `a` from the pillow at that height,
 * depth DEPTH × a), turned by the same yaw and pitch his eyes use. Every anchor
 * is a point on it; `z > 0` means facing the viewer, so a wrapping part has a
 * front piece (after the body) and a back piece (before it, hidden by it).
 */
const DEPTH = 0.8;
/** The camera looks down on him a little, so a ring shows as an ellipse. */
const VIEW = 0.2;

export interface P3 { x: number; y: number; z: number }

/** The angle that tips a ring's front down on screen: the camera's tilt less his nod up. */
export function ringTilt(H: Head): number {
  return VIEW - H.pitch;
}

/** A point `t` radians round the ring centred at body height `yc` (0 = the front, ±π/2 = his sides). */
export function ringPoint(H: Head, yc: number, a: number, t: number, depth = DEPTH): P3 {
  const c = depth * a;
  const X = a * Math.sin(t);
  const Z = c * Math.cos(t);
  const cy = Math.cos(H.yaw);
  const sy = Math.sin(H.yaw);
  // His outline does not narrow when he turns, so the turned ring is scaled to keep its sides on it.
  const k = a / Math.hypot(a * cy, c * sy);
  const x1 = (X * cy + Z * sy) * k;
  const z1 = -X * sy + Z * cy;
  const phi = ringTilt(H);
  return { x: x1, y: yc + z1 * Math.sin(phi), z: z1 * Math.cos(phi) - yc * Math.sin(phi) };
}

/** A ring's outline, `n` points all the way round, starting at the front. */
export function ringPoints(H: Head, yc: number, a: number, n = 40, depth = DEPTH): P3[] {
  const out: P3[] = [];
  for (let i = 0; i <= n; i++) out.push(ringPoint(H, yc, a, (i / n) * Math.PI * 2, depth));
  return out;
}

/** The pieces of a closed ring facing the viewer (`front`) or turned away: each a run of points. */
export function splitRing(pts: P3[], front: boolean): P3[][] {
  const runs: P3[][] = [];
  let cur: P3[] = [];
  for (const q of pts) {
    if (q.z >= 0 === front) cur.push(q);
    else if (cur.length) {
      runs.push(cur);
      cur = [];
    }
  }
  if (cur.length) runs.push(cur);
  // The ring starts at the front: a front run that wraps past the end joins the first.
  if (runs.length > 1 && pts[0].z >= 0 === front && pts[pts.length - 1].z >= 0 === front) {
    const last = runs.pop() as P3[];
    runs[0] = last.concat(runs[0]);
  }
  return runs;
}

/** The ring at a fraction `v` of ry (negative = up): its centre, half width and wobble included. */
function ringAt(H: Head, v: number): { yc: number; a: number } {
  const yc = v * H.ry + H.physDy * H.ry * 0.05;
  return { yc, a: halfWidthAt(yc, H.rx, H.ry, BODY_EXP) };
}

/** His neck line: low on him, and always a gap of at least 0.12 ry below his eyes. */
function neckY(H: Head): number {
  const eyeBottom = H.eyes ? Math.max(H.eyes[0][1], H.eyes[1][1]) : H.ry * 0.1;
  return Math.min(H.ry * 0.9, Math.max(COLLAR_V * H.ry, eyeBottom + 0.22 * H.ry));
}

export function headAnchors(H: Head): Anchors {
  const { rx, ry } = H;
  const wx = H.physDx * rx * 0.05;
  const phi = ringTilt(H);
  const lift = -Math.sin(H.pitch) * ry * 0.12;
  const r0 = ringAt(H, RIM_V);
  const rim = { cx: wx, cy: r0.yc, a: r0.a, b: Math.max(0.5, DEPTH * r0.a * Math.abs(Math.sin(phi))) };
  const colY = neckY(H) + H.physDy * ry * 0.05;
  const ca = halfWidthAt(colY, rx, ry, BODY_EXP);
  const collar = { cx: wx, cy: colY, a: ca, b: Math.max(0.5, DEPTH * ca * Math.abs(Math.sin(phi))) };
  const sx = rx / 36;
  const sy = ry / 31;
  const [eyeL, eyeR] = H.eyes ?? [[-12 * sx, sy], [12 * sx, sy]];
  return {
    crown: [wx, -ry * (1 - PILLOW_BOW) + lift + H.physDy * ry * 0.05],
    rim,
    rimLeft: [rim.cx - rim.a, rim.cy],
    rimRight: [rim.cx + rim.a, rim.cy],
    rimTop: [rim.cx, rim.cy - rim.b],
    eyeL,
    eyeR,
    eyeLine: (eyeL[1] + eyeR[1]) / 2,
    collar,
    neck: [collar.cx, collar.cy],
    base: ry * (1 - PILLOW_BOW),
  };
}

/** The board's own Groovy shows through on the seasonal cards: the glints in his eyes. */
function boardEye(s: Shape): boolean {
  return s.f?.toUpperCase() === "#FFFFFF" && /^M(36|60) 61A2 1\.3/.test(s.d);
}

/** The six-month reward: a gold crown with a single pale-blue diamond. */
const DIAMOND_CROWN: Art = {
  front: [
    { d: "M30 33L29 19L38 25L44 12L50 21L56 12L62 25L71 19L70 33Z", f: "#E0B84A", s: "#B8902A", w: 0.8 },
    { d: "M30 29H70V33H30Z", f: "#C99A2E" },
    { d: "M36 31A1.2 1.2 0 1 0 38.4 31A1.2 1.2 0 1 0 36 31ZM61.6 31A1.2 1.2 0 1 0 64 31A1.2 1.2 0 1 0 61.6 31Z", f: "#FFE08A" },
    { d: "M42.8 12A1.4 1.4 0 1 0 45.6 12A1.4 1.4 0 1 0 42.8 12ZM54.4 12A1.4 1.4 0 1 0 57.2 12A1.4 1.4 0 1 0 54.4 12Z", f: "#FFE08A" },
    { d: "M27.8 19A1.3 1.3 0 1 0 30.4 19A1.3 1.3 0 1 0 27.8 19ZM69.6 19A1.3 1.3 0 1 0 72.2 19A1.3 1.3 0 1 0 69.6 19Z", f: "#FFE08A" },
    { d: "M50 19L55 25L50 31L45 25Z", f: "#CFF3FF", s: "#7FD4FF", w: 0.6 },
    { d: "M45 25H55M50 19V31", s: "#FFFFFF", w: 0.4, o: 0.7 },
    { d: "M47.5 22.5L49 21", s: "#FFFFFF", w: 0.7, cap: 1 },
  ],
};

/** The board's flat glasses arms (out to the card's edge): his run back behind his head. */
const BOARD_ARM = /M\d+(?:\.\d+)? \d+(?:\.\d+)?H(?:14|86)/g;

/** Shapes drawn from the head model instead (round 3M item 3): straps, bands and the arms of glasses. */
const PROCEDURAL: Partial<Record<string, number[]>> = { piratePatch: [0], pilotGoggles: [0], headphones: [0, 1] };

function clean(art: Art, id = ""): Art {
  const armed = ["roundSpecs", "shades", "heartGlasses"].includes(id);
  const drop = PROCEDURAL[id] ?? [];
  const keep = (list?: Shape[]) =>
    list?.filter((s, i) => !boardEye(s) && !(list === art.front && drop.includes(i))).map((s) => (armed && !s.f ? { ...s, d: s.d.replace(BOARD_ARM, "").trim() } : s));
  return { behind: keep(art.behind), body: keep(art.body), front: keep(art.front) };
}

/** Every item's art. The cards' eye colours are the board's, not the item's: left out. */
const ITEM_ART: Record<string, Art> = Object.fromEntries([
  ...Object.entries(WARDROBE_ART).map(([id, a]) => [id, clean(a, id)]),
  ...Object.entries(SEASONAL_ART).map(([id, a]) => [id, clean(a)]),
  ["diamondCrown", DIAMOND_CROWN],
]);

/** An item's shapes (tests). */
export function itemArt(item: Accessory): Art | undefined {
  return ITEM_ART[item];
}

// ── Layers and transitions ────────────────────────────────────────────────────

let scratch: HTMLCanvasElement | null = null;

/**
 * Draws `fn` at `alpha` as one layer, so overlapping parts don't show through
 * each other while an item fades.
 */
function withLayer(ctx: Ctx, alpha: number, fn: (c: Ctx) => void) {
  if (alpha >= 0.999) {
    ctx.save();
    fn(ctx);
    ctx.restore();
    return;
  }
  const W = ctx.canvas.width;
  const Hh = ctx.canvas.height;
  scratch ??= document.createElement("canvas");
  if (scratch.width < W || scratch.height < Hh) {
    scratch.width = Math.max(scratch.width, W);
    scratch.height = Math.max(scratch.height, Hh);
  }
  const s = scratch.getContext("2d");
  if (!s) return;
  s.setTransform(1, 0, 0, 1, 0, 0);
  s.clearRect(0, 0, W, Hh);
  s.setTransform(ctx.getTransform());
  s.save();
  fn(s);
  s.restore();
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha *= alpha;
  ctx.drawImage(scratch, 0, 0, W, Hh, 0, 0, W, Hh);
  ctx.restore();
}

export interface OutfitState {
  /** 0 = gone, 1 = fully on. Animated by the engine. */
  presence: number;
  /** Groovy's mailbox morph: items fade away as he turns into a box. */
  morph: number;
}

/** Turned round (a roll): what sits on his face is behind him. */
function faceTurnedAway(H: Head): boolean {
  return Math.cos(H.yaw) < 0;
}

function layerAlpha(st: OutfitState): number {
  const morphFade = 1 - Math.min(1, Math.max(0, (st.morph - 0.3) / 0.2));
  return morphFade * Math.min(1, st.presence * 2.5);
}

/** The item's way in: hats drop and settle, glasses slide down, neck items pop. */
function arrive(ctx: Ctx, item: Accessory, H: Head, p: number) {
  const posP = Ease.back(p);
  const slot = SLOT_OF[item];
  if (slot === "head") {
    const s = 0.85 + 0.15 * posP;
    ctx.translate(0, -(1 - posP) * H.ry);
    ctx.scale(s, s);
  } else if (slot === "face") {
    ctx.translate(0, -(1 - p) * 0.25 * H.ry);
  } else {
    const s = Math.max(0.001, 0.6 + 0.4 * posP);
    ctx.translate(0, H.ry * 0.85);
    ctx.scale(s, s);
    ctx.translate(0, -H.ry * 0.85);
  }
}

/** The board's eyes (Wardrobe.dc.html): what face items were drawn around. */
const BOARD_EYES = { l: 38, r: 62, y: 62 } as const;
/** How far a face item's art reaches beyond a lens on the board, in board units (arms excluded). */
const FACE_REACH = 24;
/** Half the width of a hat's art on the board, where it is narrower than his rim. */
const HAT_HALF: Partial<Record<Accessory, number>> = { acornCap: 28, backwardsCap: 26, leafCrown: 31 };
/** The board point the pool ring hangs from: his middle. */
const ANCHOR = { middle: [50, 80] } as const;
/**
 * The board body (a 72×62 rounded rect, corner 22, at 14,30) at RIM_V and
 * COLLAR_V: the line's height and half width, mapped onto his rim and collar.
 */
const BOARD_RIM = { y: 61 + ART_RIM_V * 31, hw: 14 + Math.sqrt(22 * 22 - (52 - (61 + ART_RIM_V * 31)) ** 2) } as const;
const BOARD_COLLAR = { y: 61 + COLLAR_V * 31, hw: 14 + Math.sqrt(22 * 22 - (61 + COLLAR_V * 31 - 70) ** 2) } as const;

/** Hats and crowns whose rim goes round his head: the far half shows behind him. */
const RIMMED = new Set<Accessory>([
  "leafCrown", "acornCap", "mushroomCap", "flowerCrown", "bucketHat", "backwardsCap", "miniTopHat", "diamondCrown",
  "pumpkinCap", "bobbleBeanie", "eggshellHat", "strawSunHat", "watermelonCap",
]);
/** Neck items that go all the way round him: the back half shows behind him. */
const COLLARED = new Set<Accessory>([
  "bandana", "leafScarf", "seedPendant", "neckPhones", "goldChain", "flowerLei",
  "candyCornScarf", "knitStripeScarf", "jingleBellCollar", "daisyChain", "shellNecklace",
]);
/** Worn parts that hang or stand loose and swing the most: ears, stalks, antennae, pom-poms, antlers, wings. */
const LOOSE = new Set<Accessory>(["bunnyEarBand", "bobbleBeanie", "acornCap", "antenna", "twigAntlers", "batWingBand", "cloudBuddy", "beretPin", "littleGhostPal", "pastelRibbonBow"]);
/** Neck items that hang from a point and swing like a pendulum. */
const HANGING = new Set<Accessory>(["necktie", "seedPendant", "goldChain", "jingleBellCollar", "shellNecklace", "leafScarf", "candyCornScarf", "knitStripeScarf", "flowerLei", "bowTie"]);
/** Glasses with arms that run back along his head. */
const ARMED = new Set<Accessory>(["roundSpecs", "shades", "heartGlasses"]);

/** The item's main colour, a shade darker: its far side, in shadow. */
function backColour(art: Art): string | null {
  const f = [...(art.front ?? []), ...(art.body ?? [])].find((sh) => typeof sh.f === "string" && /^#[0-9a-f]{6}$/i.test(sh.f))?.f;
  if (!f) return null;
  const n = parseInt(f.slice(1), 16);
  const d = (v: number) => Math.round(v * 0.62);
  return `rgb(${d(n >> 16)},${d((n >> 8) & 255)},${d(n & 255)})`;
}

/**
 * The parts of an item that sit behind his body (round 3H item 1): the far half
 * of a hat's rim, the back of a collar, the arms of glasses. Drawn before the
 * body, so only what shows past his outline is seen.
 */
function drawBackParts(ctx: Ctx, item: Accessory, art: Art, H: Head) {
  const slot = SLOT_OF[item];
  const col = backColour(art);
  if (!col) return;
  const A = headAnchors(H);
  if ((slot === "head" && RIMMED.has(item)) || (slot === "neck" && COLLARED.has(item))) {
    const r = slot === "head" ? A.rim : A.collar;
    const back = splitRing(ringPoints(H, r.cy, r.a * 1.04), false);
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(1, r.b * (slot === "head" ? 0.7 : 0.9));
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    for (const run of back) {
      ctx.beginPath();
      run.forEach((q, i) => (i ? ctx.lineTo(q.x + r.cx, q.y) : ctx.moveTo(q.x + r.cx, q.y)));
      ctx.stroke();
    }
  }
  for (const st of wrapStrokes(item, H, A, art)) strokeRuns(ctx, st, false);
  if (item === "headphones") drawCups(ctx, art, H, A, false);
}

/** How an item narrows as he turns, never below 0.6 so nothing vanishes. */
export function narrowing(yaw: number, strength: number): number {
  return Math.max(0.6, 1 - (1 - Math.max(0, Math.cos(yaw))) * strength);
}

/**
 * Where a face item sits: the board's two eyes onto his (their middle, their
 * spacing, never under 0.6 of the full face's, and the line between them), so a
 * lens is always on its eye. What lies beyond a lens on the board (a visor's
 * ends, a patch's strap) is foreshortened with the turn so its outer edge stays
 * inside his outline: `kL` and `kR` scale the board left of the left lens and
 * right of the right lens.
 */
function faceFit(H: Head) {
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  const [l, r] = H.eyes ?? [[-12 * sx, sy], [12 * sx, sy]];
  const front = Math.abs(12 * sx * 2) || 1;
  const span = Math.hypot(r[0] - l[0], r[1] - l[1]);
  const full = H.eyes ? span / Math.max(0.05, Math.cos(H.yaw)) : front;
  const half = (BOARD_EYES.r - BOARD_EYES.l) / 2;
  const k = Math.max(span, full * 0.6) / (BOARD_EYES.r - BOARD_EYES.l);
  const ky = full / (BOARD_EYES.r - BOARD_EYES.l);
  const cx = (l[0] + r[0]) / 2;
  const cy = (l[1] + r[1]) / 2;
  const rot = Math.atan2(r[1] - l[1], r[0] - l[0]);
  const hw = halfWidthAt(cy, H.rx, H.ry, BODY_EXP) * 0.98;
  const side = (room: number) => Math.min(k, Math.max(0.1 * k, room) / FACE_REACH);
  return { cx, cy, rot, k, ky, kL: side(hw + cx - half * k), kR: side(hw - cx - half * k) };
}

// ── Things that go round him (round 3M item 3) ───────────────────────────────

interface Stroke { pts: P3[]; color: string; lw: number; closed?: boolean }

/** The ring angle whose point on the ring at `yc` is nearest to screen x. */
function ringAngleAt(H: Head, yc: number, a: number, x: number): number {
  let best = 0;
  let bd = Infinity;
  for (let k = 0; k < 72; k++) {
    const t = (k / 72) * Math.PI * 2 - Math.PI;
    const q = ringPoint(H, yc, a, t);
    const d = Math.abs(q.x - x) + (q.z < -a * 0.3 ? a : 0);
    if (d < bd) {
      bd = d;
      best = t;
    }
  }
  return best;
}

/** A path round him from a screen point `from` (on the front of his head) to `toT` radians round, the ring height easing to `yEnd`. */
function wrapPath(H: Head, from: [number, number], yEnd: number, toT: number, n = 16): P3[] {
  const a0 = halfWidthAt(from[1], H.rx, H.ry, BODY_EXP);
  const t0 = ringAngleAt(H, from[1], a0, from[0]);
  const base = ringPoint(H, from[1], a0, t0);
  const out: P3[] = [];
  for (let k = 0; k <= n; k++) {
    const u = k / n;
    const yc = from[1] + (yEnd - from[1]) * u;
    const q = ringPoint(H, yc, halfWidthAt(yc, H.rx, H.ry, BODY_EXP), t0 + (toT - t0) * u);
    const w = (1 - u) * (1 - u);
    out.push({ x: q.x + (from[0] - base.x) * w, y: q.y + (from[1] - base.y) * w, z: q.z });
  }
  return out;
}

/** The straps, bands and arms an item draws from his head model. `x` offsets are in body space. */
function wrapStrokes(item: Accessory, H: Head, A: Anchors, art: Art): Stroke[] {
  const ey = A.eyeLine;
  const R = H.R;
  const ry = H.ry;
  const dark = backColour(art) ?? "#222";
  switch (item) {
    case "piratePatch":
      // From the patch up and round the side of his head, and a short one down behind the other ear.
      return [
        { pts: wrapPath(H, A.eyeR, ey - ry * 0.3, -Math.PI * 0.92), color: "#1B1F26", lw: R * 0.05 },
        { pts: wrapPath(H, A.eyeR, ey + ry * 0.1, Math.PI * 0.92), color: "#1B1F26", lw: R * 0.05 },
      ];
    case "glowVisor": {
      const a = halfWidthAt(ey, H.rx, H.ry, BODY_EXP);
      return [{ pts: ringPoints(H, ey, a * 0.93), color: "#2FBF5F", lw: ry * 0.3, closed: true }];
    }
    case "pilotGoggles": {
      const yc = A.rim.cy - 0.18 * ry;
      return [{ pts: ringPoints(H, yc, halfWidthAt(yc, H.rx, H.ry, BODY_EXP)), color: "#7A5230", lw: R * 0.07, closed: true }];
    }
    case "headphones": {
      // Over the crown from ear to ear, seated on his head: along his outline's upper half (a meridian of the head model).
      const earY = ey;
      const ax = halfWidthAt(earY, H.rx, H.ry, BODY_EXP);
      const top: [number, number][] = [];
      for (let k = 0; k <= 96; k++) {
        const [x, y] = pillowXY((k / 96) * Math.PI * 2, H.rx, H.ry, BODY_EXP);
        if (y <= earY) top.push([x, y]);
      }
      top.sort((p, q) => p[0] - q[0]);
      const pts: P3[] = top.map(([x, y]) => archPoint(H, x * 0.985, y * 0.99, 0.04 * ax, ax));
      return [{ pts, color: "#2B2F36", lw: R * 0.11 }];
    }
    case "roundSpecs":
    case "shades":
    case "heartGlasses": {
      const lens = Math.hypot(A.eyeR[0] - A.eyeL[0], A.eyeR[1] - A.eyeL[1]) * 0.42;
      const a = halfWidthAt(ey, H.rx, H.ry, BODY_EXP);
      const out: Stroke[] = [];
      for (const [e, sd] of [[A.eyeL, -1], [A.eyeR, 1]] as const) {
        const t0 = ringAngleAt(H, e[1], a, e[0] + sd * lens);
        const pts: P3[] = [];
        for (let k = 0; k <= 10; k++) {
          const u = k / 10;
          pts.push(ringPoint(H, e[1] - ry * 0.02 * u, a, t0 + (sd * Math.PI * 0.8 - t0) * u));
        }
        out.push({ pts, color: dark, lw: Math.max(1, R * 0.05) });
      }
      return out;
    }
    default:
      return [];
  }
}

/** A point of the head model from a position in his unturned frame (X sideways, Y down, Z towards us). */
function archPoint(H: Head, X: number, Y: number, Z: number, a: number): P3 {
  const cy = Math.cos(H.yaw);
  const sy = Math.sin(H.yaw);
  const k = a / Math.hypot(a * cy, DEPTH * a * sy);
  const z1 = -X * sy + Z * cy;
  const phi = ringTilt(H);
  return { x: (X * cy + Z * sy) * k, y: Y + z1 * Math.sin(phi), z: z1 * Math.cos(phi) - Y * Math.sin(phi) };
}

/** Draws a stroke's far pieces (back) or near pieces (front); the back ones are hidden by the body drawn over them. */
function strokeRuns(ctx: Ctx, st: Stroke, front: boolean, dx = 0) {
  const runs = st.closed ? splitRing(st.pts, front) : splitPath(st.pts, front);
  ctx.strokeStyle = st.color;
  ctx.lineWidth = Math.max(1, st.lw);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (const run of runs) {
    ctx.beginPath();
    run.forEach((q, i) => (i ? ctx.lineTo(q.x + dx, q.y) : ctx.moveTo(q.x + dx, q.y)));
    ctx.stroke();
  }
}

function splitPath(pts: P3[], front: boolean): P3[][] {
  const runs: P3[][] = [];
  let cur: P3[] = [];
  for (const q of pts) {
    if (q.z >= 0 === front) cur.push(q);
    else if (cur.length) {
      runs.push(cur);
      cur = [];
    }
  }
  if (cur.length) runs.push(cur);
  return runs;
}

/** Headphone cups on his ears: the near one in front and bigger, the far one behind him, thinner as it turns away. */
function drawCups(ctx: Ctx, art: Art, H: Head, A: Anchors, front: boolean) {
  const shapes = art.front ?? [];
  const ax = halfWidthAt(A.eyeLine, H.rx, H.ry, BODY_EXP);
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  for (const sd of [-1, 1]) {
    const q = archPoint(H, sd * ax, A.eyeLine, 0, ax);
    if (q.z >= -ax * 0.05 !== front) continue;
    const turn = Math.abs(Math.sin(H.yaw));
    const near = q.z >= 0;
    const w = (0.5 + 0.5 * turn) * (near ? 1.1 : 0.9);
    const cup = sd < 0 ? [shapes[0], shapes[2]] : [shapes[1], shapes[3]];
    ctx.save();
    ctx.translate(q.x + sd * sx * 3, q.y);
    ctx.scale(sx * w, sy);
    ctx.translate(-(sd < 0 ? 13.5 : 86.5), -60);
    drawShapes(ctx, cup.filter(Boolean) as Shape[]);
    ctx.restore();
  }
}

/**
 * Board space for an item, placed on its anchor (the caller drew nothing
 * yet). Exported for the placement test.
 */
export function placeItem(ctx: Ctx, item: Accessory, H: Head) {
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  const slot = SLOT_OF[item];
  const wobbleX = H.physDx * H.rx * 0.05;
  const wobbleY = H.physDy * H.ry * 0.05;
  if (slot === "face") {
    const f = faceFit(H);
    ctx.translate(f.cx, f.cy);
    ctx.rotate(f.rot);
    ctx.scale(f.k, f.ky);
    ctx.translate(-(BOARD_EYES.l + BOARD_EYES.r) / 2, -BOARD_EYES.y);
    return;
  }
  if (item !== "poolRing" && (slot === "head" || slot === "neck")) {
    // The board's rim (or collar) line onto his: its middle and its width, so
    // the item's seat lies on his real outline at every turn and nod.
    const A = headAnchors(H);
    const ring = slot === "head" ? A.rim : A.collar;
    const seat = slot === "head" ? BOARD_RIM : BOARD_COLLAR;
    const kx = narrowing(H.yaw, slot === "head" ? 0.25 : 0.5);
    // Sized from the rim: a hat is at least 0.92 of his width there (round 3L item 4).
    const fit = slot === "head" ? Math.max(1, (0.92 * seat.hw) / (HAT_HALF[item] ?? seat.hw)) : 1;
    // The seat is the ring's front point on his head model, so it follows his turn and nod.
    const F = ringPoint(H, ring.cy, ring.a, 0);
    ctx.translate(ring.cx + F.x * (slot === "head" ? 0.5 : 1), F.y + (item === "neckPhones" ? 8 * sy : 0)); // its cups hang low on his chest
    // Worn parts lag and swing from their seat: hats tip against the motion, dangling parts hang from it.
    const sw = H.swing ?? 0;
    ctx.rotate(slot === "head" ? -H.physDx * 0.1 - sw * (LOOSE.has(item) ? 0.9 : 0.3) : sw * (HANGING.has(item) ? 0.5 : 0.2));
    // Dangling parts stretch a little when he hops (the body's own squash already scales everything).
    const hop = slot === "neck" ? 1 + H.physDy * 0.12 : 1;
    ctx.scale((ring.a / seat.hw) * kx * fit, sy * (slot === "head" ? Math.min(fit, 1.15) : 1) * hop);
    ctx.translate(-50, -seat.y);
    return;
  }
  const [ax, ay] = ANCHOR.middle;
  ctx.translate(Math.sin(H.yaw) * H.rx * 0.3 + wobbleX, -Math.sin(H.pitch) * H.ry * 0.2 + wobbleY);
  ctx.translate((ax - 50) * sx, (ay - 61) * sy);
  ctx.scale(sx, sy);
  ctx.translate(-ax, -ay);
}

let bodyPath: { key: string; path: Path2D } | null = null;
function bodyOutline(H: Head): Path2D {
  const key = `${H.rx.toFixed(1)}|${H.ry.toFixed(1)}`;
  if (bodyPath?.key === key) return bodyPath.path;
  const path = new Path2D();
  for (let i = 0; i <= 64; i++) {
    const [x, y] = pillowXY((i / 64) * Math.PI * 2, H.rx, H.ry, BODY_EXP);
    if (i) path.lineTo(x, y);
    else path.moveTo(x, y);
  }
  path.closePath();
  bodyPath = { key, path };
  return path;
}

/**
 * Round 3L items 2 and 3: a soft shadow on his body where the item touches it,
 * along the rim's, the collar's or the frame's own curve; clipped to the body.
 */
function drawContactShadow(ctx: Ctx, item: Accessory, H: Head) {
  if (H.R < 14) return;
  const slot = SLOT_OF[item];
  const A = headAnchors(H);
  const off = H.R * 0.07;
  ctx.save();
  ctx.clip(bodyOutline(H));
  ctx.strokeStyle = "rgba(0,0,0,0.22)";
  ctx.lineWidth = H.R * 0.12;
  ctx.lineCap = "round";
  ctx.shadowColor = "rgba(0,0,0,0.22)";
  ctx.shadowBlur = H.R * 0.14;
  ctx.beginPath();
  if (slot === "face") {
    if (!ARMED.has(item)) { ctx.restore(); return; }
    const lens = Math.hypot(A.eyeR[0] - A.eyeL[0], A.eyeR[1] - A.eyeL[1]) * 0.22;
    for (const e of [A.eyeL, A.eyeR]) {
      ctx.moveTo(e[0] + lens, e[1] + off);
      ctx.ellipse(e[0], e[1] + off, lens, lens * 0.9, 0, 0, Math.PI);
    }
  } else if ((slot === "head" && RIMMED.has(item)) || (slot === "neck" && COLLARED.has(item))) {
    const r = slot === "head" ? A.rim : A.collar;
    const k = Math.max(0.6, Math.cos(H.yaw));
    ctx.ellipse(r.cx + Math.sin(H.yaw) * r.a * 0.3, r.cy + off, r.a * k, Math.max(0.5, r.b), 0, 0, Math.PI);
  } else {
    ctx.restore();
    return;
  }
  ctx.stroke();
  ctx.restore();
}

function drawItem(ctx: Ctx, item: Accessory, art: Art, H: Head, layers: readonly ("behind" | "body" | "front")[]) {
  if (SLOT_OF[item] === "face") {
    const f = faceFit(H);
    if (f.kL < f.k * 0.99 || f.kR < f.k * 0.99) {
      drawFaceBands(ctx, art, layers, f);
      return;
    }
  }
  if (DOME.has(item) && layers.includes("front")) {
    ctx.save();
    domeRegion(ctx, H, false);
    ctx.clip();
    placeItem(ctx, item, H);
    for (const l of layers) drawShapes(ctx, visibleShapes(item, art[l], H));
    ctx.restore();
    return;
  }
  placeItem(ctx, item, H);
  for (const l of layers) drawShapes(ctx, visibleShapes(item, art[l], H));
}

/** Shapes to draw: the mushroom's pale underside only shows where its rim tips up towards him. */
function visibleShapes(item: Accessory, shapes: Shape[] | undefined, H: Head): Shape[] | undefined {
  if (item !== "mushroomCap" || !shapes || ringTilt(H) < -0.02) return shapes;
  return shapes.filter((sh) => sh.f !== "#F4E3D0" && sh.s !== "#D2B79A");
}

/** Hats that cover the top of his head down to their rim (crowns, which are open rings, do not). */
const DOME = new Set<Accessory>([
  "acornCap", "mushroomCap", "pumpkinCap", "bobbleBeanie", "eggshellHat", "watermelonCap", "bucketHat", "backwardsCap",
]);

/** The path of everything above the rim's front arc (extended sideways, so a brim past his outline is kept). */
function domeRegion(ctx: Ctx, H: Head, close: boolean) {
  const r = headAnchors(H).rim;
  const front = splitRing(ringPoints(H, r.cy, r.a), true)[0] ?? [];
  const pts = [...front].sort((p, q) => p.x - q.x);
  const big = H.rx * 4;
  ctx.beginPath();
  if (!pts.length) {
    ctx.rect(-big, -big, 2 * big, big + r.cy);
    return;
  }
  ctx.moveTo(r.cx + pts[0].x - big, pts[0].y);
  for (const q of pts) ctx.lineTo(r.cx + q.x, q.y);
  ctx.lineTo(r.cx + pts[pts.length - 1].x + big, pts[pts.length - 1].y);
  ctx.lineTo(r.cx + pts[pts.length - 1].x + big, -big);
  ctx.lineTo(r.cx + pts[0].x - big, -big);
  if (close) ctx.closePath();
}

/** The hat's own colour, filling the crown of his head down to the rim so nothing shows through. */
function drawDome(ctx: Ctx, item: Accessory, art: Art, H: Head) {
  const f = [...(art.front ?? []), ...(art.body ?? [])].find((sh) => typeof sh.f === "string" && /^#[0-9a-f]{6}$/i.test(sh.f))?.f;
  if (!f) return;
  ctx.save();
  ctx.clip(bodyOutline(H));
  domeRegion(ctx, H, true);
  ctx.fillStyle = f;
  ctx.fill();
  ctx.restore();
  void item;
}

/** A face item in three board bands (left of the left lens, between, right of the right lens), each at its own width. */
function drawFaceBands(ctx: Ctx, art: Art, layers: readonly ("behind" | "body" | "front")[], f: ReturnType<typeof faceFit>) {
  const h = (BOARD_EYES.r - BOARD_EYES.l) / 2;
  const bands: [number, number, number, number, number][] = [
    // [clip from, clip to, board x held in place, its offset from the middle, scale]
    [-1000, BOARD_EYES.l, BOARD_EYES.l, -h * f.k, f.kL],
    [BOARD_EYES.l - 0.2, BOARD_EYES.r + 0.2, 50, 0, f.k],
    [BOARD_EYES.r, 1000, BOARD_EYES.r, h * f.k, f.kR],
  ];
  for (const [from, to, at, off, kx] of bands) {
    ctx.save();
    ctx.translate(f.cx, f.cy);
    ctx.rotate(f.rot);
    ctx.translate(off, 0);
    ctx.scale(kx, f.ky);
    ctx.translate(-at, -BOARD_EYES.y);
    ctx.beginPath();
    ctx.rect(from, -1000, to - from, 2000);
    ctx.clip();
    for (const l of layers) drawShapes(ctx, art[l]);
    ctx.restore();
  }
}

/**
 * The parts behind Groovy's body. `ctx` is in body space (translated to the body
 * centre, tilted and squashed exactly like the body).
 */
export function drawOutfitBehind(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  const alpha = layerAlpha(st);
  if (!art || alpha <= 0.005) return;
  const face = SLOT_OF[outfit] === "face";
  // Turned away, his glasses are behind him; anything that is always behind stays there.
  const layers = face && faceTurnedAway(H) ? (["behind", "body", "front"] as const) : (["behind"] as const);
  const back = !(face && faceTurnedAway(H));
  if (!back && !layers.some((l) => art[l]?.length)) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  withLayer(ctx, alpha, (l) => {
    if (back) {
      l.save();
      drawBackParts(l, outfit, art, H);
      l.restore();
    }
    drawItem(l, outfit, art, H, layers);
  });
  ctx.restore();
}

/** The parts in front of Groovy, drawn after the body and the eyes. */
export function drawOutfitFront(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  if (!art || (SLOT_OF[outfit] === "face" && faceTurnedAway(H))) return;
  const alpha = layerAlpha(st);
  if (alpha <= 0.005) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  // The board puts glasses that hide the eyes under them; on him they go over.
  withLayer(ctx, alpha, (l) => {
    drawContactShadow(l, outfit, H);
    if (DOME.has(outfit)) drawDome(l, outfit, art, H);
    const A = headAnchors(H);
    for (const st of wrapStrokes(outfit, H, A, art)) strokeRuns(l, st, true);
    if (outfit === "headphones") drawCups(l, art, H, A, true);
    else drawItem(l, outfit, art, H, ["body", "front"]);
  });
  ctx.restore();
}

// ── Wardrobe icons ────────────────────────────────────────────────────────────

/** The board's body: a 72×62 rounded rect at (14, 30). */
const ICON_BODY = "M36 30H64A22 22 0 0 1 86 52V70A22 22 0 0 1 64 92H36A22 22 0 0 1 14 70V52A22 22 0 0 1 36 30Z";
let iconBody: Path2D | null = null;

/** A little Groovy wearing `item`, as on the boards, in a `size`×`size` icon. */
function iconGroovy(ctx: Ctx, size: number, item: Accessory) {
  const art = ITEM_ART[item];
  // The boards' view, -8…104 high: hats reach up to about y -4, neck items down to 100.
  const k = size / 112;
  ctx.save();
  ctx.translate(size / 2 - 50 * k, 8 * k);
  ctx.scale(k, k);
  drawShapes(ctx, art?.behind);
  iconBody ??= new Path2D(ICON_BODY);
  const g = ctx.createLinearGradient(70, 30, 30, 92);
  g.addColorStop(0, "#F1F3F5");
  g.addColorStop(1, "#C6C9CF");
  ctx.fillStyle = g;
  ctx.fill(iconBody);
  ctx.fillStyle = "#1A1412";
  for (const ex of [38, 62]) {
    ctx.beginPath();
    ctx.ellipse(ex, 62, 5.5, 4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.save();
  ctx.clip(iconBody);
  drawShapes(ctx, art?.body, "clipped");
  drawShapes(ctx, art?.front, "clipped");
  ctx.restore();
  drawShapes(ctx, art?.body, "free");
  drawShapes(ctx, art?.front, "free");
  ctx.restore();
}

/** One wardrobe button's picture; "none" is a crossed-out circle. */
export function drawWardrobeIcon(ctx: Ctx, size: number, selection: Outfit) {
  ctx.clearRect(0, 0, size, size);
  if (selection === "none") {
    const r = 6.5;
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.strokeStyle = "#454850";
    ctx.lineWidth = 1.4;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.82, 0, Math.PI * 2);
    ctx.moveTo(-r * 0.56, r * 0.56);
    ctx.lineTo(r * 0.56, -r * 0.56);
    ctx.stroke();
    ctx.restore();
    return;
  }
  iconGroovy(ctx, size, selection);
}
